-- P3 lifecycle SQL, generated by sqlc.
-- name: SetBuildInfra :exec
UPDATE build SET infra_failure= @infra_failure, infra_reason=sqlc.narg(infra_reason) WHERE id= @id;

-- name: ListBuildCases :many
SELECT test_case_id, stage FROM test_run WHERE build_id= @build_id ORDER BY test_case_id;

-- name: LockRepository :one
SELECT * FROM repository WHERE name= @name FOR UPDATE;

-- name: ListDetectionHistory :many
WITH eligible AS (
 SELECT b.id AS build_id, tr.outcome, b.branch, b.started_at, b.infra_failure,
 COALESCE(b.tested_tree_sha,'')::text AS tested_tree_sha, COALESCE(tr.failure_hash,'')::text AS failure_hash
 FROM test_run tr JOIN build b ON b.id = tr.build_id
 WHERE tr.test_case_id = @test_case_id AND tr.stage = 'BLOCKING' AND NOT b.infra_failure
 AND b.id > COALESCE((SELECT max((evidence->>'released_after_build_id')::bigint)
 FROM quarantine WHERE test_case_id = @test_case_id AND state = 'RELEASED'),0)
), recent AS (
 SELECT * FROM eligible ORDER BY started_at DESC,build_id DESC LIMIT @run_window
), main_runs AS (
 SELECT * FROM eligible WHERE branch = @default_branch AND outcome IN ('PASSED','FAILED','ERROR')
 ORDER BY started_at DESC,build_id DESC LIMIT @main_window
)
SELECT * FROM recent UNION SELECT * FROM main_runs ORDER BY started_at DESC,build_id DESC;

-- name: CountRecentTests :one
SELECT count(DISTINCT tr.test_case_id)::bigint FROM test_run tr
JOIN (SELECT id FROM build WHERE repository_id= @repository_id
 ORDER BY started_at DESC,id DESC LIMIT @build_window) b ON b.id=tr.build_id;

-- name: CountActiveQuarantines :one
SELECT count(*)::bigint FROM quarantine q JOIN test_case tc ON tc.id=q.test_case_id
WHERE tc.repository_id= @repository_id AND q.state='QUARANTINED';

-- name: GetActiveForTest :one
SELECT * FROM quarantine WHERE test_case_id= @test_case_id AND state='QUARANTINED';

-- name: InsertQuarantine :one
INSERT INTO quarantine(test_case_id,state,reason_rule,evidence,manual)
VALUES(@test_case_id,'QUARANTINED',@reason_rule,@evidence,@manual) RETURNING *;

-- name: ListReleaseOutcomes :many
SELECT tr.outcome FROM test_run tr JOIN build b ON b.id=tr.build_id
WHERE tr.test_case_id= @test_case_id AND tr.stage='QUARANTINE' AND NOT b.infra_failure
 AND b.id > @after_build_id
ORDER BY b.started_at DESC,b.id DESC;

-- name: SetReleaseProgress :exec
UPDATE quarantine SET consecutive_passes= @passes,
 state=CASE WHEN @release::boolean THEN 'RELEASED' ELSE state END,
 released_at=CASE WHEN @release::boolean THEN clock_timestamp() ELSE released_at END,
 evidence=CASE WHEN @release::boolean THEN evidence||jsonb_build_object('released_after_build_id',
 (SELECT COALESCE(max(b.id),0) FROM build b JOIN test_case tc ON tc.repository_id=b.repository_id WHERE tc.id=quarantine.test_case_id))
 ELSE evidence END
WHERE quarantine.id= @id AND state='QUARANTINED';

-- name: FindCaseByName :one
SELECT * FROM test_case WHERE repository_id= @repository_id AND class_name= @class_name AND method_name= @method_name;

-- name: GetQuarantineRepository :one
SELECT r.name FROM quarantine q JOIN test_case tc ON tc.id=q.test_case_id JOIN repository r ON r.id=tc.repository_id WHERE q.id= @id;

-- name: ManualRelease :execrows
UPDATE quarantine SET state='RELEASED',released_at=clock_timestamp(),manual=true,
 evidence=evidence||jsonb_build_object('release_reason',@reason::text,'released_after_build_id',
 (SELECT COALESCE(max(b.id),0) FROM build b JOIN test_case tc ON tc.repository_id=b.repository_id WHERE tc.id=quarantine.test_case_id))
WHERE quarantine.id= @id AND state='QUARANTINED';

-- name: InsertFlakyAlert :exec
INSERT INTO alert(type,repository_id,build_id,payload)
SELECT 'FLAKY',@repository_id,@build_id,@payload
WHERE NOT EXISTS(SELECT 1 FROM alert WHERE type='FLAKY' AND build_id= @build_id AND payload->>'test_case_id'= @test_case_id::text);

-- name: RepositoryBuildWatermark :one
SELECT COALESCE(max(id),0)::bigint FROM build WHERE repository_id = @repository_id;
